const PORTAL_CONFIG_B64='';
const SESSION_TTL=60*60*12;
const DEFAULT_MODEL='deepseek/deepseek-v3.2';
const FALLBACK_MODEL='mistralai/mistral-small-3.2-24b-instruct';
const DG_PERMANENT_KEY='univers:access:permanent';
const DG_GRANT_PREFIX='univers:access:grant:';

function json(d,s=200,h={}){return new Response(JSON.stringify(d),{status:s,headers:{'Content-Type':'application/json; charset=utf-8','Cache-Control':'no-store',...h}})}
function cfg(){try{const b=Uint8Array.from(atob(PORTAL_CONFIG_B64),c=>c.charCodeAt(0));return JSON.parse(new TextDecoder().decode(b))}catch(_){return{id:'portail',title:'Portail NyXia',shortTitle:'Portail',mission:'',activeAgents:[],agents:[]}}}
const PORTAL=cfg(),AGENTS=Object.fromEntries((PORTAL.agents||[]).map(a=>[String(a.key||'').toLowerCase(),a])),ACTIVE=new Set(PORTAL.activeAgents||[]);
const norm=v=>String(v||'').trim().toLowerCase(),tok=()=>crypto.randomUUID()+crypto.randomUUID();
function emailLocalPart(email){return norm(email).split('@')[0]||''}
function normalizedNameToken(v){return String(v||'').trim().toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g,'').replace(/[^a-z0-9]+/g,'')}
function validFirstname(name,email){const n=String(name||'').trim();if(!n)return'';if(n.includes('@'))return'';const a=normalizedNameToken(n),b=normalizedNameToken(emailLocalPart(email));if(a&&b&&a===b)return'';return n}
function firstWordName(v){const n=String(v||'').trim();return n?n.split(/\s+/)[0]:''}
async function resolveFirstname(env,email,client,submitted){
 const candidates=[client&&client.firstName,client&&client.firstname,firstWordName(client&&client.name)];
 for(const c of candidates){const ok=validFirstname(c,email);if(ok)return ok}
 if(env.DB){try{const row=await env.DB.prepare('SELECT full_name FROM users WHERE lower(email)=lower(?) LIMIT 1').bind(email).first();const ok=validFirstname(firstWordName(row&&row.full_name),email);if(ok)return ok}catch(_){}}
 return validFirstname(submitted,email)
}
async function session(env,t){if(!t)return null;const r=await env.CASHFLOW_KV.get('portal:session:'+t);if(!r)return null;try{const s=JSON.parse(r);if(!s||s.portal!==PORTAL.id||!validFirstname(s.firstname,s.email))return null;const client=JSON.parse(await env.CASHFLOW_KV.get('client:'+s.email)||'{}');if((client.authVersion||'')!==(s.authVersion||''))return null;return s}catch(_){return null}}
function cookieValue(req,name){const raw=req.headers.get('Cookie')||'';for(const part of raw.split(';')){const i=part.indexOf('=');if(i<0)continue;if(part.slice(0,i).trim()===name)return decodeURIComponent(part.slice(i+1).trim())}return''}
function sessionCookie(token,maxAge=SESSION_TTL){return 'nyxia_portal_session='+encodeURIComponent(token)+'; Path=/; Max-Age='+maxAge+'; HttpOnly; Secure; SameSite=Lax'}
function clearSessionCookie(){return 'nyxia_portal_session=; Path=/; Max-Age=0; HttpOnly; Secure; SameSite=Lax'}
async function browserSession(req,env){return session(env,cookieValue(req,'nyxia_portal_session'))}
function loginRedirect(req){const u=new URL('/login.html',req.url);return Response.redirect(u.toString(),302)}
function isProtectedHtml(path){if(['/premiere-connexion.html','/mot-de-passe-oublie.html','/reinitialiser-mot-de-passe.html'].includes(path))return false;if(path==='/'||path===''||path==='/index.html'||path==='/login.html'||path==='/login')return false;return /\.html$/i.test(path)}

const DG_CAMPAIGNS_KEY='univers:degustations',DG_ACTIVATION_PREFIX='univers:access:activation:',DG_OWNER_EMAIL='magiquebusiness@gmail.com';
function dgEmail(v) { return String(v || '').trim().toLowerCase(); }
function dgId(v) { return String(v || '').trim().toLowerCase().replace(/[^a-z0-9_-]/g, '').slice(0, 100); }
function dgNow() { return new Date().toISOString(); }
function dgGrantKey(email, campaignId, portalId) { return DG_GRANT_PREFIX + encodeURIComponent(dgEmail(email)) + ':' + dgId(campaignId) + ':' + dgId(portalId); }
function dgActivationKey(email, campaignId) { return DG_ACTIVATION_PREFIX + encodeURIComponent(dgEmail(email)) + ':' + dgId(campaignId); }
async function dgReadCampaigns(env) {
  const raw = await env.CASHFLOW_KV.get(DG_CAMPAIGNS_KEY);
  if (!raw) return [];
  try { const list = JSON.parse(raw); return Array.isArray(list) ? list : []; } catch (_) { return []; }
}
async function dgReadPermanent(env) {
  let list = [];
  const raw = await env.CASHFLOW_KV.get(DG_PERMANENT_KEY);
  if (raw) { try { const p = JSON.parse(raw); if (Array.isArray(p)) list = p; } catch (_) {} }
  const owner = list.find((x) => dgEmail(x && x.email) === DG_OWNER_EMAIL);
  if (owner) {
    owner.email = DG_OWNER_EMAIL; owner.role = 'owner'; owner.allPortals = true; owner.portalIds = []; owner.protected = true;
    if (!owner.createdAt) owner.createdAt = dgNow();
  } else {
    list.unshift({ email: DG_OWNER_EMAIL, role: 'owner', allPortals: true, portalIds: [], note: 'OWNER NyXia — accès permanent protégé', protected: true, createdAt: dgNow(), updatedAt: dgNow() });
  }
  await env.CASHFLOW_KV.put(DG_PERMANENT_KEY, JSON.stringify(list));
  return list;
}
async function dgStartPendingCampaign(env, email, campaignId) {
  email = dgEmail(email); campaignId = dgId(campaignId);
  const campaigns = await dgReadCampaigns(env);
  const campaign = campaigns.find((c) => c.id === campaignId);
  if (!campaign) return null;
  const aKey = dgActivationKey(email, campaignId);
  let activation = null;
  const raw = await env.CASHFLOW_KV.get(aKey);
  if (raw) { try { activation = JSON.parse(raw); } catch (_) {} }
  if (!activation) return null;
  if (!activation.pending && activation.startedAt) return activation;
  const startedAt = dgNow();
  const expiresAt = campaign.fixedEndAt || new Date(Date.parse(startedAt) + Number(campaign.durationHours || 72) * 3600000).toISOString();
  activation.pending = false; activation.startedAt = startedAt; activation.expiresAt = expiresAt; activation.updatedAt = dgNow();
  await env.CASHFLOW_KV.put(aKey, JSON.stringify(activation));
  // Même compteur pour TOUS les portails de cette campagne.
  for (const portalId of campaign.portalIds || []) {
    const key = dgGrantKey(email, campaignId, portalId);
    const gRaw = await env.CASHFLOW_KV.get(key); if (!gRaw) continue;
    try {
      const g = JSON.parse(gRaw); g.pending = false; g.startedAt = startedAt; g.expiresAt = expiresAt; g.updatedAt = dgNow();
      await env.CASHFLOW_KV.put(key, JSON.stringify(g));
    } catch (_) {}
  }
  return activation;
}
async function dgGrantsFor(env, email, portalId) {
  const prefix = DG_GRANT_PREFIX + encodeURIComponent(dgEmail(email)) + ':';
  const list = await env.CASHFLOW_KV.list({ prefix }); const out=[];
  for (const k of list.keys || []) {
    const raw=await env.CASHFLOW_KV.get(k.name); if(!raw)continue;
    try { const g=JSON.parse(raw); if(g.portalId===portalId){g.key=k.name;out.push(g);} } catch(_){}
  }
  return out.sort((a,b)=>String(b.createdAt||'').localeCompare(String(a.createdAt||'')));
}
async function dgCheckAccess(env, email, portalId) {
  email = dgEmail(email); portalId = dgId(portalId);
  if (!email || !portalId) return { allowed:false, reason:'missing' };
  // 1) OWNER / STAFF / TEST permanent.
  const permanent = await dgReadPermanent(env);
  const p = permanent.find((x) => dgEmail(x.email) === email);
  if (p && (p.allPortals || (p.portalIds || []).includes(portalId))) return { allowed:true, accessType:'permanent', role:p.role || 'staff', expiresAt:null };
  // 2) Accès déjà acheté / permanent existant dans le système client. Ne jamais le casser.
  const clientRaw = await env.CASHFLOW_KV.get('client:' + email);
  if (clientRaw) {
    try {
      const client = JSON.parse(clientRaw); const products = Array.isArray(client.products) ? client.products.map((x)=>String(x).toLowerCase()) : [];
      if (client.active !== false && products.includes(portalId)) return { allowed:true, accessType:'purchased', role:client.role || 'client', expiresAt:null };
    } catch (_) {}
  }
  // 3) Dégustation temporaire.
  let grants = await dgGrantsFor(env, email, portalId);
  const pending = grants.find((g) => g.pending);
  if (pending) {
    await dgStartPendingCampaign(env, email, pending.campaignId);
    grants = await dgGrantsFor(env, email, portalId);
  }
  const campaignsForExpiry = await dgReadCampaigns(env);
  const grantEffectiveExpiry = (g) => { const c = campaignsForExpiry.find(x => x.id === g.campaignId); return c && c.fixedEndAt ? Math.min(Date.parse(g.expiresAt || c.fixedEndAt), Date.parse(c.fixedEndAt)) : Date.parse(g.expiresAt || ''); };
  const grantStarted = (g) => { const c = campaignsForExpiry.find(x => x.id === g.campaignId); return !c || !c.fixedStartAt || Date.parse(c.fixedStartAt) <= Date.now(); };
  const active = grants.find((g) => g.expiresAt && grantStarted(g) && grantEffectiveExpiry(g) > Date.now());
  if (active) return { allowed:true, accessType:'temporary', campaignId:active.campaignId, campaignName:active.campaignName, startedAt:active.startedAt, expiresAt:active.expiresAt };
  const awaiting = grants.find((g) => g.expiresAt && !grantStarted(g) && grantEffectiveExpiry(g) > Date.now());
  if (awaiting) return { allowed:false, reason:'not_started', campaignId:awaiting.campaignId, startsAt:(campaignsForExpiry.find(x=>x.id===awaiting.campaignId)||{}).fixedStartAt };
  const expired = grants.find((g) => g.expiresAt && grantEffectiveExpiry(g) <= Date.now());
  if (expired) {
    const campaigns = await dgReadCampaigns(env); const c = campaigns.find((x)=>x.id===expired.campaignId) || {};
    return { allowed:false, reason:'expired', campaignId:expired.campaignId, campaignName:expired.campaignName, expiresAt:expired.expiresAt, afterExpiry:c.afterExpiry || null, continuation:c.continuation || [] };
  }
  return { allowed:false, reason:'no_access' };
}
async function checkAccess(env,email){const access=await dgCheckAccess(env,email,PORTAL.id);return {...access,type:access.accessType}}
async function passwordHash(password,salt){const enc=new TextEncoder(),key=await crypto.subtle.importKey('raw',enc.encode(password),'PBKDF2',false,['deriveBits']);const bits=await crypto.subtle.deriveBits({name:'PBKDF2',salt:enc.encode(salt),iterations:100000,hash:'SHA-256'},key,256);return [...new Uint8Array(bits)].map(x=>x.toString(16).padStart(2,'0')).join('')}
async function passwordMatches(client,password){if(client.passwordHash&&client.salt)return await passwordHash(password,client.salt)===client.passwordHash;return !!client.password&&password===client.password}
async function changePassword(req,env){
 const b=await req.json().catch(()=>({})),s=await session(env,b.token||cookieValue(req,'nyxia_portal_session'));
 if(!s)return json({error:'Reconnecte-toi pour changer ton mot de passe.'},401);
 const password=String(b.password||'');if(password.length<8||password!==b.confirm)return json({error:'Choisis au moins 8 caractères et confirme le même mot de passe.'},400);
 const client=JSON.parse(await env.CASHFLOW_KV.get('client:'+s.email)||'{}');if(!await passwordMatches(client,String(b.currentPassword||'')))return json({error:'Mot de passe actuel incorrect.'},401);
 client.salt=tok();client.passwordHash=await passwordHash(password,client.salt);client.authVersion=tok();delete client.password;
 await env.CASHFLOW_KV.put('client:'+s.email,JSON.stringify(client));return json({ok:true},200,{'Set-Cookie':clearSessionCookie()});
}
async function passwordProxy(req,path){const response=await fetch('https://univers.nyxia.top'+path,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({...await req.json(),portalHost:new URL(req.url).hostname})});return new Response(response.body,{status:response.status,headers:{'Content-Type':'application/json','Cache-Control':'no-store'}})}

async function login(req,env){
 const b=await req.json().catch(()=>({}));
 const email=norm(b.email);
 const password=String(b.password||'');
 const firstname=String(b.firstname||'').trim();
 if(!firstname)return json({error:'Prénom requis.'},400);
 if(!email)return json({error:'Courriel requis.'},400);
 const cr=await env.CASHFLOW_KV.get('client:'+email);let client={email};try{client={...client,...JSON.parse(cr||'{}')}}catch(_){}
 if(client.active===false||!password||!await passwordMatches(client,password))return json({error:'Mot de passe incorrect.'},401);
 const access=await checkAccess(env,email);if(!access.allowed)return json({error:'Aucun accès actif à ce portail.'},403);

 const t=tok(),sess={email,firstname,authVersion:client.authVersion||'',portal:PORTAL.id,accessType:access.type,expiresAt:access.expiresAt||null};
 await env.CASHFLOW_KV.put('portal:session:'+t,JSON.stringify(sess),{expirationTtl:SESSION_TTL});
 return json({success:true,token:t,firstname:sess.firstname,user:sess},200,{'Set-Cookie':sessionCookie(t)})
}
async function logout(req,env){let t='';try{const b=await req.json();t=String(b.token||'')}catch(_){}if(!t)t=cookieValue(req,'nyxia_portal_session');if(t){try{await env.CASHFLOW_KV.delete('portal:session:'+t)}catch(_){}}return json({success:true},200,{'Set-Cookie':clearSessionCookie()})}
async function requireSession(req,env){const u=new URL(req.url);let t=u.searchParams.get('token')||u.searchParams.get('t')||'';if(req.method!=='GET'){try{const c=req.clone();const b=await c.json();t=b.token||t}catch(_){}}return session(env,t)}
async function retrieve(env,agent,q){if(!env.AI||!env.VECTORIZE_INDEX||!q)return'';try{const e=await env.AI.run('@cf/baai/bge-m3',{text:[q]}),r=await env.VECTORIZE_INDEX.query(e.data[0],{topK:6,returnMetadata:'all',namespace:agent});return(r.matches||[]).filter(x=>x.score>.35).map(x=>x.metadata?.texte_original||'').filter(Boolean).join('\n\n---\n\n')}catch(_){return''}}
async function formations(env,agent){
 const out=[];
 const agentKey=norm(agent);
 const portalKey=norm(PORTAL.id);
 if(!agentKey||!portalKey)return out;
 let cur;
 const prefix='formation:'+portalKey+':'+agentKey+':';
 do{
  const l=await env.CASHFLOW_KV.list({prefix,cursor:cur});
  for(const k of l.keys||[]){
   try{
    const d=JSON.parse(await env.CASHFLOW_KV.get(k.name)||'{}');
    if(!d||!d.id)continue;
    if(norm(d.agent)!==agentKey)continue;
    if(norm(d.portail)!==portalKey)continue;
    out.push(d);
   }catch(_){}
  }
  cur=l.list_complete?null:l.cursor;
 }while(cur);
 out.sort((a,b)=>(a.ordre||0)-(b.ordre||0)||String(a.titre||'').localeCompare(String(b.titre||'')));
 return out;
}
function renderBlock(b,first){const t=String(b?.type||'texte').toLowerCase();if(t==='texte'||t==='intervention')return String(b.contenu||'').replace(/\{prenom\}/gi,first||'toi');if(t==='exercice')return['🎯 '+(b.objectif||''),b.consigne||''].filter(Boolean).join('\n\n');if(t==='image')return (b.legende?b.legende+'\n':'')+'[IMAGE: '+b.url+']';if(t==='audio')return (b.intro?b.intro+'\n':'')+'[AUDIO: '+b.url+']';if(t==='video'||t==='vidéo')return (b.intro?b.intro+'\n':'')+'[VIDEO: '+b.url+']';if(t==='lien')return (b.intro?b.intro+'\n':'')+'[LINK: '+b.url+'|'+(b.titre||'Ouvrir')+']';return''}
function formationProgressKey(s,agent){return'formation-progress:'+PORTAL.id+':'+norm(s?.email)+':'+norm(agent)}
async function readFormationProgress(env,s,agent,fs){
 const key=formationProgressKey(s,agent);
 let st={schemaVersion:2,completed:{},progress:{}};
 try{const raw=JSON.parse(await env.CASHFLOW_KV.get(key)||'{}');if(raw&&typeof raw==='object')st={...st,...raw}}catch(_){}
 if(!st.completed||typeof st.completed!=='object'||Array.isArray(st.completed))st.completed={};
 if(!st.progress||typeof st.progress!=='object'||Array.isArray(st.progress))st.progress={};
 /* Migration transparente de l'ancien format : mi / bi / started appartenaient à la première formation. */
 if(fs?.length&&st.started!==undefined&&!Object.keys(st.progress).length){
  st.progress[fs[0].id]={mi:Number(st.mi)||0,bi:Number(st.bi)||0,started:!!st.started};
  delete st.mi;delete st.bi;delete st.started;
 }
 st.schemaVersion=2;
 return{key,st}
}
function firstIncompleteFormation(fs,st){return(fs||[]).find(f=>!st.completed?.[f.id])||null}
function progressForFormation(st,id){const p=st.progress?.[id]||{};return{mi:Math.max(0,Number(p.mi)||0),bi:Math.max(0,Number(p.bi)||0),started:!!p.started}}
async function saveFormationProgressState(env,key,st){await env.CASHFLOW_KV.put(key,JSON.stringify(st))}

function formationById(fs,id){return(fs||[]).find(f=>String(f.id)===String(id))||null}
function formationStatus(fs,st,id){
 const f=formationById(fs,id);if(!f)return'missing';
 if(st.completed?.[f.id])return'completed';
 const current=firstIncompleteFormation(fs,st);if(current&&current.id===f.id)return'active';
 return'locked';
}
function blockAtFormation(f,p){
 const mods=Array.isArray(f?.modules)?f.modules:[];
 let mi=Math.max(0,Number(p.mi)||0),bi=Math.max(0,Number(p.bi)||0);
 while(mi<mods.length&&bi>=(Array.isArray(mods[mi]?.blocs)?mods[mi].blocs:[]).length){mi++;bi=0}
 if(mi>=mods.length)return{done:true,mods,mi,bi};
 const m=mods[mi],blocs=Array.isArray(m?.blocs)?m.blocs:[];
 return{done:false,mods,mi,bi,m,b:blocs[bi]};
}
function formationContent(f,pos,first,review=false){
 if(!pos||pos.done)return'';
 const body=renderBlock(pos.b,first);
 const showHeader=Number(pos.bi||0)===0;
 const header=showHeader
  ? (review?'🔁 **Révision · ':'🎓 **')+(f.titre||'Formation')+' — '+nxModuleHeading(pos.m,pos.mi)+'**\n\n'
  : '';
 return header+body;
}

function formationControl(message){
 const n=norm(message).normalize('NFD').replace(/[\u0300-\u036f]/g,'').trim();
 if(/^(suite|suivant|suivante|prochaine etape|continue)$/.test(n))return'advance';
 if(/reprend|reprendre/.test(n)&&/(formation|cours)/.test(n))return'resume';
 if(/commenc|debut|demarr/.test(n)&&/(formation|cours)/.test(n))return'start';
 if(/formation|cours/.test(n))return'resume';
 return null;
}
async function formationTurn(env,s,agent,msg,requestedId='',requestedMode=''){
 const action=formationControl(msg);if(!action)return null;
 const fs=await formations(env,agent);if(!fs.length)return null;
 const state=await readFormationProgress(env,s,agent,fs),st=state.st;
 const requested=formationById(fs,requestedId);
 let mode=String(requestedMode||'').toLowerCase();
 let f=requested||firstIncompleteFormation(fs,st);
 if(!f)return{content:'🏆 Tu as terminé toutes les formations actuellement disponibles dans ce parcours.',formationDone:true};
 const status=formationStatus(fs,st,f.id);
 if(status==='locked')return{content:'🔒 Cette formation n’est pas encore débloquée. Ouvre « Mon Parcours » pour voir où tu es rendue.'};
 if(status==='completed')mode='review';

 if(mode==='review'){
  st.review=st.review&&typeof st.review==='object'?st.review:{};
  let p={mi:0,bi:0,started:true,...(st.review[f.id]||{})};
  if(action==='advance')p.bi++;
  const pos=blockAtFormation(f,p);
  if(pos.done){
   st.review[f.id]={mi:0,bi:0,started:true};
   await saveFormationProgressState(env,state.key,st);
   return{content:'✅ Révision de **'+(f.titre||'la formation')+'** terminée. Ta progression principale n’a pas changé.',reviewDone:true,formationId:f.id};
  }
  p.mi=pos.mi;p.bi=pos.bi;p.started=true;st.review[f.id]=p;
  await saveFormationProgressState(env,state.key,st);
  return{content:formationContent(f,pos,s.firstname,true),review:true,formationId:f.id};
 }

 let p=progressForFormation(st,f.id);
 if(action==='advance'&&p.started)p.bi++;else p.started=true;
 const pos=blockAtFormation(f,p);
 if(pos.done){
  st.completed[f.id]={completedAt:new Date().toISOString(),titre:f.titre||f.id};
  delete st.progress[f.id];
  const next=firstIncompleteFormation(fs,st);
  await saveFormationProgressState(env,state.key,st);
  if(next)return{content:'✅ **'+(f.titre||'Formation')+' terminée.**\n\n🎓 La prochaine étape de ton parcours est maintenant **'+(next.titre||'la formation suivante')+'**. Clique sur **Commencer ma formation** pour poursuivre ici.',formationDone:true,formationId:f.id,nextFormationId:next.id};
  return{content:'🏆 **'+(f.titre||'Formation')+' terminée.**\n\n✨ Tu as terminé toutes les formations actuellement disponibles dans ce parcours.',formationDone:true,formationId:f.id,allCompleted:true};
 }
 p.mi=pos.mi;p.bi=pos.bi;p.started=true;st.progress[f.id]=p;
 await saveFormationProgressState(env,state.key,st);
 return{content:formationContent(f,pos,s.firstname,false),formationId:f.id};
}
async function formationOpen(req,env){
 const b=await req.json().catch(()=>({})),s=await session(env,b.token);if(!s)return json({error:'Session expirée.'},401);
 const agent=norm(b.agent),formationId=String(b.formationId||'');if(!ACTIVE.has(agent))return json({error:'Personnage non disponible.'},403);
 const fs=await formations(env,agent),state=await readFormationProgress(env,s,agent,fs),st=state.st,f=formationById(fs,formationId);
 if(!f)return json({error:'Formation introuvable.'},404);
 const status=formationStatus(fs,st,f.id);
 if(status==='locked')return json({error:'Cette formation n’est pas encore débloquée.'},403);
 if(status==='completed'){
  st.review=st.review&&typeof st.review==='object'?st.review:{};
  st.review[f.id]={mi:0,bi:0,started:true};
  const pos=blockAtFormation(f,st.review[f.id]);
  await saveFormationProgressState(env,state.key,st);
  return json({content:formationContent(f,pos,s.firstname,true),mode:'review',formationId:f.id,status:'completed'});
 }
 let p=progressForFormation(st,f.id);p.started=true;
 const pos=blockAtFormation(f,p);
 if(pos.done){
  st.completed[f.id]={completedAt:new Date().toISOString(),titre:f.titre||f.id};
  delete st.progress[f.id];
  await saveFormationProgressState(env,state.key,st);
  return json({content:'✅ **'+(f.titre||'Formation')+' terminée.** Clique sur « Commencer ma formation » pour poursuivre ici.',mode:'follow',formationId:f.id,status:'completed',formationDone:true});
 }
 p.mi=pos.mi;p.bi=pos.bi;st.progress[f.id]=p;
 await saveFormationProgressState(env,state.key,st);
 return json({content:formationContent(f,pos,s.firstname,false),mode:'follow',formationId:f.id,status:'active'});
}

function sanitizeAssistantContent(content){
 const fallback='Je suis là avec toi. Dis-moi ce que tu veux faire avancer.';
 let s=String(content||'').trim();
 if(!s)return fallback;
 s=s
  .replace(/\[(?:VIDEO|AUDIO|PDF|LINK|PHOTO)\s*:[^\]]+\]/gi,'')
  .replace(/\[[^\]]+\]\((https?:\/\/[^\s)]+)\)/gi,'')
  .replace(/https?:\/\/[^\s<]+/gi,'')
  .replace(/\n{3,}/g,'\n\n')
  .trim();
 return s||fallback;
}

