async function nxPremiumRead(env,key){
  if(!env.CASHFLOW_KV)return null;
  try{const raw=await env.CASHFLOW_KV.get('nyxia:personnage-profil:'+String(key).toLowerCase());return raw?JSON.parse(raw):null}catch(_){return null}
}
const NX_PREMIUM_FIELDS=['name','visibleRole','sub','shortDescription','biography','mission','prompt','systemPrompt','personality','values','tone','languageStyle','favoriteExpressions','avoidExpressions','expertise','skills','methods','teachingStyle','ethics','limits','canDo','cannotDo','welcomeMessage','greeting','suggestions','image','welcomeVideo','voiceName','voiceId','modelPrimary','modelFallback','vectorNamespace','resources'];
function nxPremiumMerge(base,profile){
  const a={...base};if(!profile)return a;
  for(const k of NX_PREMIUM_FIELDS)if(Object.prototype.hasOwnProperty.call(profile,k)){
    if(k==='voiceId'&&!String(profile[k]||'').trim())continue;
    a[k]=profile[k];
  }
  if(Object.prototype.hasOwnProperty.call(profile,'visibleRole'))a.sub=profile.visibleRole;
  if(Object.prototype.hasOwnProperty.call(profile,'welcomeMessage'))a.greeting=profile.welcomeMessage;
  if(Object.prototype.hasOwnProperty.call(profile,'mission'))a.prompt=profile.mission;
  return a;
}
async function nxPremiumAgent(env,key,base){return nxPremiumMerge(base,await nxPremiumRead(env,key))}
function nxPremiumInstructions(p){
  if(!p)return '';
  const labels={name:'Nom',visibleRole:'Rôle',biography:'Biographie',mission:'Mission',systemPrompt:'Instructions du personnage',personality:'Personnalité',values:'Valeurs',tone:'Ton',languageStyle:'Langage',favoriteExpressions:'Expressions favorites',avoidExpressions:'Expressions à éviter',expertise:'Expertise',skills:'Compétences',methods:'Méthodes',teachingStyle:'Pédagogie',ethics:'Éthique',limits:'Limites',canDo:'Peut faire',cannotDo:'Ne doit pas faire'};
  return Object.entries(labels).filter(([k])=>typeof p[k]==='string'&&p[k].trim()).map(([k,label])=>label+' : '+p[k]).join('\n');
}
async function nxPremiumPrompt(env,key,base){
  const p=await nxPremiumRead(env,key);if(!p)return base;
  return base+'\n\nFICHE PREMIUM ACTUELLE : les éléments suivants remplacent les anciennes descriptions de ce personnage. Conserve les règles techniques du portail.\n'+nxPremiumInstructions(p);
}

const NX_PREMIUM_KEYS=()=>[...ACTIVE].filter(k=>AGENTS[k]);
const NX_PREMIUM_HYDRATE="if(data&&data.valid&&data.premiumProfiles){\n  Object.keys(data.premiumProfiles).forEach(function(key){\n    var p=data.premiumProfiles[key];\n    if(typeof ALPHA_INFO!=='undefined'&&ALPHA_INFO&&ALPHA_INFO[key])Object.assign(ALPHA_INFO[key],p);\n    if(typeof AGENT_IMAGES!=='undefined'&&AGENT_IMAGES&&Object.prototype.hasOwnProperty.call(p,'image'))AGENT_IMAGES[key]=p.image;\n    if(typeof AGENT_WELCOME_VIDEO!=='undefined'&&AGENT_WELCOME_VIDEO&&Object.prototype.hasOwnProperty.call(p,'welcomeVideo'))AGENT_WELCOME_VIDEO[key]=p.welcomeVideo;\n    if(typeof AGENT_SUGGESTIONS!=='undefined'&&AGENT_SUGGESTIONS&&Array.isArray(p.suggestions))AGENT_SUGGESTIONS[key]=p.suggestions;\n    if(typeof PORTAL_AGENT_META!=='undefined'&&PORTAL_AGENT_META&&PORTAL_AGENT_META[key])Object.assign(PORTAL_AGENT_META[key],p);\n    if(typeof PORTAL_AGENT!=='undefined'&&PORTAL_AGENT&&typeof _currentAgent!=='undefined'&&_currentAgent===key)Object.assign(PORTAL_AGENT,p);\n  });\n}\n";
async function nxPremiumPresentation(env,keys){
  const result={};
  await Promise.all(keys.map(async key=>{
    const p=await nxPremiumRead(env,key);if(!p)return;
    const pub={};
    for(const k of ['name','sub','image','welcomeVideo','greeting','suggestions'])if(Object.prototype.hasOwnProperty.call(p,k))pub[k]=p[k];
    if(Object.prototype.hasOwnProperty.call(p,'visibleRole'))pub.sub=p.visibleRole;
    if(Object.prototype.hasOwnProperty.call(p,'welcomeMessage'))pub.greeting=p.welcomeMessage;
    result[key]=pub;
  }));
  return result;
}
function nxPremiumHydrateSource(text){
  if(!text.includes('/api/check-auth')||text.includes('data.premiumProfiles'))return text;
  const injection=NX_PREMIUM_HYDRATE;
  return text.replace(/\.then\(\s*function\s*\(\s*data\s*\)\s*\{/g,match=>match+'\n'+injection+'\n')
    .replace(/\.then\(\s*data\s*=>\s*\{/g,match=>match+'\n'+injection+'\n');
}
const nyxBookingOriginalWorker = {
  async fetch(request,env,ctx){
    const flow=await nxFormationFlowApi(request,env,ctx);if(flow)return flow;const live=await nxLiveApi(request,env,ctx);if(live)return live;
    const response=await nxOriginalWorker.fetch(request,env,ctx);
    const path=new URL(request.url).pathname;
    if(path==='/api/check-auth'&&response.ok){
      let data;try{data=await response.clone().json()}catch(_){return response}
      if(data.valid){
        data.premiumProfiles=await nxPremiumPresentation(env,NX_PREMIUM_KEYS());
        const headers=new Headers(response.headers);headers.delete('Content-Length');headers.delete('ETag');headers.set('Cache-Control','no-store');
        return new Response(JSON.stringify(data),{status:response.status,headers});
      }
      return response;
    }
    const type=response.headers.get('Content-Type')||'';
    if(response.ok&&request.method==='GET'&&(type.includes('text/html')||type.includes('javascript'))&&
      !/\/(login|index|premiere-connexion|mot-de-passe)/.test(path)){
      const original=await response.clone().text(),updated=nxPremiumHydrateSource(original);
      if(updated!==original){
        const headers=new Headers(response.headers);headers.delete('Content-Length');headers.delete('ETag');headers.set('Cache-Control','no-store');
        return new Response(updated,{status:response.status,headers});
      }
    }
    return response;
  }
};


// Liaison commune de l’index aux réservations : aucun écran ni formulaire ajouté.
export default {
  ...nyxBookingOriginalWorker,
  async fetch(request,env,ctx){
    // Agenda éditorial : session et propriété du podcast vérifiées côté serveur.
    if(new URL(request.url).pathname.startsWith('/api/editorial/')){
      const response=await handleEditorial(request,env,async token=>{
        const r=await nxOriginalWorker.fetch(new Request(new URL('/api/check-auth',request.url),{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({token})}),env,ctx);
        if(!r.ok)return {valid:false};return r.json();
      });
      if(response)return response;
    }
    // Nolan : routes de mémoire multipodcasts (indépendantes de la Formation Vivante).
    if(new URL(request.url).pathname.startsWith('/api/nolan/projects')){
      const nolanResponse=await handleNolanProjects(request,env,async token=>{
        const authResponse=await nxOriginalWorker.fetch(new Request(new URL('/api/check-auth',request.url),{
          method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({token})
        }),env,ctx);
        if(!authResponse.ok)return {valid:false};
        return authResponse.json();
      });
      if(nolanResponse)return nolanResponse;
    }
    const page=new URL(request.url).pathname.replace(/\/+$/,'')||'/';
    const index=request.method==='GET'&&['/','/index','/index.html'].includes(page);
    let input=request;
    if(index){const h=new Headers(request.headers);h.delete('If-None-Match');h.delete('If-Modified-Since');input=new Request(request,{headers:h});}
    const response=await nyxBookingOriginalWorker.fetch(input,env,ctx);
    if(!index||!response.ok||!(response.headers.get('Content-Type')||'').includes('text/html'))return response;
    const text=await response.clone().text();
    if(text.includes('/closer/booking-bridge.js'))return response;
    const position=text.toLowerCase().lastIndexOf('</body>');
    if(position<0)return response;
    const tag='<script src="https://univers.nyxia.top/closer/booking-bridge.js" data-nyxia-portal defer></script>\n';
    const html=text.slice(0,position)+tag+text.slice(position),headers=new Headers(response.headers);
    headers.delete('Content-Length');headers.delete('ETag');
    return new Response(html,{status:response.status,headers});
  }
};

const NX_LIVE_PORTAL=env=>PORTAL.id;
async function NX_LIVE_OPEN(env,s,agent,id){const fs=await formations(env,agent);if(!fs.some(f=>f.id===id))return null;return formationTurn(env,s,agent,'commencer ma formation',id)}
async function nxLiveApi(request,env,ctx){
 const u=new URL(request.url);if(!['/api/personnage/live','/api/personnage/formation/open'].includes(u.pathname))return null;
 const b=request.method==='POST'?await request.clone().json().catch(()=>({})):{};
 const token=String(b.token||u.searchParams.get('token')||''),agent=String(b.agent||u.searchParams.get('agent')||'').toLowerCase();
 if(!NX_PREMIUM_KEYS().includes(agent))return json({error:'Personnage non disponible.'},403);
 const check=await nxOriginalWorker.fetch(new Request(new URL('/api/check-auth',request.url),{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({token})}),env,ctx);
 let auth;try{auth=await check.json()}catch(_){return json({error:'Session expirée.'},401)}
 if(!auth.valid)return json({error:'Session expirée.'},401);
 if(typeof requireEricAccess==='function'&&agent==='eric'){const blocked=await requireEricAccess(env,auth);if(blocked)return blocked;}
 const raw=await nxPremiumRead(env,agent),p=raw||{};
 const portal=NX_LIVE_PORTAL(env);
 const allowed=(p.formationTriggers||[]).filter(t=>t.active!==false&&String(t.key||'').startsWith('formation:'+portal+':'+agent+':'));
 if(u.pathname==='/api/personnage/live'){
   const pub={};for(const k of ['name','sub','image','welcomeVideo','greeting','suggestions','resources'])if(Object.prototype.hasOwnProperty.call(p,k))pub[k]=p[k];
   if(Object.prototype.hasOwnProperty.call(p,'visibleRole'))pub.sub=p.visibleRole;
   if(Object.prototype.hasOwnProperty.call(p,'welcomeMessage'))pub.greeting=p.welcomeMessage;
   pub.formationTriggers=allowed;
   return new Response(JSON.stringify({profile:pub}),{headers:{'Content-Type':'application/json','Cache-Control':'private, no-store'}});
 }
 const t=allowed.find(t=>t.key===b.key);if(!t)return json({error:'Formation non disponible pour ce personnage.'},403);
 const id=t.key.split(':').slice(3).join(':'),s={email:auth.email,firstname:auth.firstname||auth.first_name||auth.userName||''};
 const result=await NX_LIVE_OPEN(env,s,agent,id);
 return result?json(result):json({error:'Formation introuvable.'},404);
}

async function NX_FLOW_LIST(env,s,agent){const fs=await formations(env,agent),{st}=await readFormationProgress(env,s,agent,fs);return fs.map(f=>({id:f.id,titre:f.titre,hasProgress:!!st.progress?.[f.id]?.started,status:formationStatus(fs,st,f.id)}))}
async function NX_FLOW_TURN(env,s,agent,id,advance,mode){return formationTurn(env,s,agent,advance?'suite':'reprendre ma formation',id,mode)}
async function nxResetFormationReview(env,s,agent,id){const fs=await formations(env,agent),state=await readFormationProgress(env,s,agent,fs);state.st.review=state.st.review||{};state.st.review[id]={mi:0,bi:0,started:true};await saveFormationProgressState(env,state.key,state.st)}
async function nxFormationFlowApi(request,env,ctx){
 const u=new URL(request.url);if(u.pathname!=='/api/personnage/formation')return null;
 const b=await request.clone().json().catch(()=>({})),agent=String(b.agent||'').toLowerCase();
 if(!NX_PREMIUM_KEYS().includes(agent))return json({error:'Personnage non disponible.'},403);
 const check=await nxOriginalWorker.fetch(new Request(new URL('/api/check-auth',request.url),{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({token:b.token||''})}),env,ctx);
 const auth=await check.json().catch(()=>({}));if(!auth.valid)return json({error:'Session expirée.'},401);
 if(typeof requireEricAccess==='function'&&agent==='eric'){const blocked=await requireEricAccess(env,auth);if(blocked)return blocked}
 const s={...auth,firstname:auth.firstname||auth.first_name||''};
 const list=await NX_FLOW_LIST(env,s,agent);
 if(b.action==='list')return json({formations:list});
 const selected=list.find(f=>f.id===b.formationId)||(!b.formationId?list.find(f=>f.status!=='locked'&&f.status!=='completed'):null);
 if(!selected)return json({error:'Formation introuvable.'},404);
 if(selected.status==='locked')return json({error:'Cette formation n’est pas encore débloquée.'},403);
 if(b.action==='restart')await nxResetFormationReview(env,s,agent,selected.id);
 const result=await NX_FLOW_TURN(env,s,agent,selected.id,b.action==='advance',b.action==='restart'||selected.status==='completed'?'review':b.mode||'');
 if(!result)return json({error:'Formation introuvable.'},404);
 result.content=String(result.content||'').replace(/\n\n— [^\n]*(?:[«“]suite[»”]|dis [«“]suite[»”])[^\n]*\s*$/i,'');
 return json({...result,formationId:result.formationId||selected.id});
}

